    const stopPolling2 = startPolling();
    const cleanup = () => {
      stopPolling2();
      dispose();
      try {
        removeLocale?.();
        removeJapaneseSettings?.();
        removeJapanese?.();
      } catch {
      }
    };
    if (typeof ctx.effect === "function") ctx.effect(() => cleanup);
    const layout = ctx.get ? ctx.get("layout") : null;
    const openPanel = () => navigate({ reason: "user" });
